  // Search for "prerequisites", "eligibility", "exam", "recertification", "renewal", "CEU"
  const getContext = (term) => {
    let results = [];
    let pos = 0;
    while ((pos = bodyText.toLowerCase().indexOf(term.toLowerCase(), pos)) !== -1) {
      results.push(bodyText.substring(Math.max(0, pos - 150), Math.min(bodyText.length, pos + 300)));
      pos += term.length + 50;
      if (results.length >= 3) break;
    }
    return results;
  };

  return {
    prerequisites: getContext("prerequisite"),
    requirements: getContext("requirements"),
    examDetails: getContext("120 questions"),
    nccaDetails: getContext("NCCA"),
    recertification: getContext("recertif")
  };
});

