const tabId = 725789364;
const details = await browserjs(tabId, () => {
  const bodyText = document.body.innerText;

  // Search for exam fee, exam length, questions, passing score, recertification, CECs
  const getContext = (term) => {
    let results = [];
    let pos = 0;
    while ((pos = bodyText.toLowerCase().indexOf(term.toLowerCase(), pos)) !== -1) {
      results.push(bodyText.substring(Math.max(0, pos - 150), Math.min(bodyText.length, pos + 300)));
      pos += term.length + 50;
      if (results.length >= 3) break;
    }
    return results;
  };

  // Look for pricing or costs
  const priceMatches = bodyText.match(/\$\d+(\.\d+)?/g);

  return {
    priceMatches: Array.from(new Set(priceMatches || [])),
    examDetails: getContext("pearson").concat(getContext("questions")),
    renewDetails: getContext("renew").concat(getContext("recert")),
    prepDetails: getContext("study plan").concat(getContext("prep"))
  };
});

console.log("ACSM Price matches:", details.priceMatches);
console.log("ACSM Exam details:", details.examDetails);
console.log("ACSM Renewal details:", details.renewDetails);

