const tabId = 725789364;
const handbookText = await browserjs(tabId, async () => {
  try {
    const res = await fetch("https://acsm.org/wp-content/uploads/2025/05/ACSM-Candidate-Handbook-July-2025.pdf");
    const buf = await res.arrayBuffer();
    const bytes = new Uint8Array(buf);
    // Convert a chunk to string to see if we can read text streams
    const textChunk = new TextDecoder('latin1').decode(bytes.slice(0, 100000));
    const matches = [];
    const keywords = ['135', '120', 'passing score', 'scaled score', '550', 'minutes', 'hours'];
    keywords.forEach(kw => {
      let idx = 0;
      while ((idx = textChunk.toLowerCase().indexOf(kw.toLowerCase(), idx)) !== -1) {
        matches.push(textChunk.substring(Math.max(0, idx - 100), Math.min(textChunk.length, idx + 150)).replace(/[^\x20-\x7E\n]/g, ' '));
        idx += kw.length + 50;
        if (matches.length >= 6) break;
      }
    });
    return { size: buf.byteLength, matches };
  } catch (e) {
    return { error: e.message };
  }
});
console.log("Handbook extracted text matches:", handbookText.matches);

