const nscaDetails = await browserjs(tabId, () => {
  const text = document.body.innerText;

  // Look for sections: requirements/eligibility, exam, recertification, pricing
  const getContext = (term) => {
    let results = [];
    let pos = 0;
    while ((pos = text.toLowerCase().indexOf(term.toLowerCase(), pos)) !== -1) {
      results.push(text.substring(Math.max(0, pos - 150), Math.min(text.length, pos + 350)));
      pos += term.length + 50;
      if (results.length >= 4) break;
    }
    return results;
  };

  return {
    prereqs: getContext("prerequisite").concat(getContext("eligib")),
    cpr: getContext("cpr"),
    exam: getContext("exam details").concat(getContext("scaled score")),
    renew: getContext("recertif").concat(getContext("renew")),
    price: getContext("$")
  };
});

