  { name: "Equinox (Miami)", url: "https://www.linkedin.com/jobs/view/personal-trainer-miami-at-equinox-4442994540" },
  { name: "Plus One Optum (Seattle)", url: "https://www.linkedin.com/jobs/view/personal-trainer-at-plus-one-an-optum-company-2148454835" }
];

for (const item of urlsToCheck) {
