  await tool.wait_for({ tabId: tId, condition: "load_state", value: "domcontentloaded", timeout_ms: 15000 });
  const data = await browserjs(tId, () => {
    const text = document.body.innerText;
    const findSection = (kw) => {
      const idx = text.toLowerCase().indexOf(kw.toLowerCase());
      return idx !== -1 ? text.substring(idx, Math.min(text.length, idx + 1200)) : null;
    };
    return {
      title: document.title,
      qual: findSection("qualifications") || findSection("requirements") || findSection("what you need") || findSection("certif") || text.substring(0, 1500)
    };
  });
  console.log(`=== ${item.name} ===`);
  console.log(data.qual);
  await tool.tabs_close({ tabId: tId });
